# aeneid-091 (XII.1-106): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Turnus certamen poscit'
PART = "Turnus Demands the Duel (XII.1–106)"
TITLE_EN = "Turnus Demands the Duel — Aeneid XII.1–106"
ABOUT = ("The last book opens with the Latins beaten twice in the field and every eye turned on Turnus, who had promised to settle the war by meeting Aeneas alone. "
"Like a wounded lion he rouses himself and tells King Latinus to prepare the treaty and the sacrifice: he will kill the Trojan, or Aeneas may have Lavinia. "
"Latinus answers calmly and at length, confessing that he broke the oracle's command to give his daughter to a stranger, and begging Turnus to spare himself and go home to his old father; his words only make the young man's fever worse. "
"Queen Amata, weeping, implores him not to fight and swears she will not outlive him. "
"Lavinia hears her mother and blushes deeply, the only moment in the poem where we see anything of her feelings, and the sight of her sets Turnus burning the more. "
"He sends a herald to Aeneas with the challenge for the next morning, calls for his horses, puts on his armour and his father's sword, made by Vulcan, and seizes a great spear, praying it will let him drag the effeminate Phrygian's perfumed hair in the dust. "
"The part closes on a simile of a young bull trying his horns before his first fight.")

U = [
(4, 'animos.',
 "Turnus, when the Latins, broken by hostile Mars,\nhe sees have given way, his promises now claimed back,\nhimself marked out by all eyes, unbidden, past appeasing, he burns\nand lifts up his spirit.",
 "When Turnus sees the Latins broken by the war's reverses and their courage spent, sees his own promise now called in and every eye singling him out, he blazes up unbidden, past all appeasing, and his pride rises.",
 "A new paragraph in Greenough, and the first lines of the last book. 'ut… videt', 'when he sees', 'ut' of time, with three infinitives of indirect statement: the Latins 'defecisse' (have given way), his promises 'reposci' (are being claimed back), he himself 'signari oculis' (is marked out by every eye). 'infractos adverso Marte', 'broken by adverse Mars': Mars stands for battle itself, the defeats of Book XI. 'sua promissa': Turnus had undertaken to meet Aeneas alone (XI.434–444, from memory). 'ultro', 'of his own accord'. 'implacabilis', 'not to be appeased'. 'attollit animos', 'raises his spirits', pride rising to the challenge. Elisions 'signar(i) oculis', 'ultr(o) implacabilis', 'attollitqu(e) animos'."),
(8, 'cruento:',
 "As in the fields of the Carthaginians\nthat lion, wounded by the hunters' heavy wound in the chest,\nonly then moves his arms, and rejoices, the maned\nshaking out on his neck muscles, and the planted spear of the lurking hunter\nfearless he breaks and roars with bloody mouth:",
 "As in the fields of Africa a lion, struck in the chest by a grievous wound from the huntsmen, only then rouses himself to fight, glories in tossing the shaggy mane upon his neck, snaps unafraid the spear the lurking hunter planted in him, and roars with bloodied jaws:",
 "'qualis… leo', 'as a lion', the first simile of the book. 'Poenorum… in arvis', 'in the fields of the Carthaginians', Africa, home of lions. 'ille', 'that (well-known) lion', the hunters' famous quarry. 'saucius… pectus', 'wounded in the chest', 'pectus' an accusative of respect (the Greek construction). 'tum demum', 'only then', once he is hurt, as Turnus once he is beaten. 'movet arma', 'moves his arms', his claws and teeth. 'comantis… toros', 'maned muscles', the '-is' accusative plural. 'latronis', 'of the man in ambush', an old sense of 'latro', here a hunter lying in wait (L&S). 'inpavidus' is Greenough's spelling of 'impavidus'. Homer compares Achilles to a wounded lion (Iliad XX.164–175, from memory). Elision 'tel(um) et'."),
(9, 'Turno.',
 "not otherwise in the kindled Turnus swells the violence.",
 "Just so the violence swells in Turnus once he is roused.",
 "'haud secus', 'not otherwise', the formula that closes a simile and turns back to the story. 'adcenso… Turno', 'in Turnus, kindled', most simply a dative of reference; 'adcenso' is Greenough's spelling of 'accenso', keeping the prefix 'ad-' unassimilated. 'gliscit', 'swells, spreads', an old word for something growing unchecked. 'violentia', 'violence', almost a name for Turnus's temper: the word comes back at 45, 'violentia Turni'. No elisions."),
(10, 'infit:',
 "Then thus he addresses the king and so, stormy, begins:",
 "Then he turns to the king, and in a storm of feeling begins:",
 "'adfatur', 'addresses', Greenough's spelling of 'affatur', from the deponent 'adfor'. 'regem', Latinus. 'turbidus', 'stormy, troubled', the adjective standing where English would use an adverb (you will see this constantly). 'infit', 'he begins (to speak)', an old defective verb found almost only in this form, a solemn word of epic. 'sic… ita', two words for 'thus', the doubled introduction of a speech. Elision 'reg(em) atque'."),
(12, 'recusent.',
 "“No delay is in Turnus; there is no reason why their words should take back\nthe cowardly Aeneadae, nor what they bargained refuse.",
 "“There is no holding back in Turnus; there is no cause for the cowardly Aeneadae to take back their words or go back on what they have agreed.",
 "Turnus's speech opens; it runs to 17. 'Nulla mora (est) in Turno': he names himself in the third person, as a public fact. 'nihil est quod…', 'there is no reason why…', with the subjunctive. 'retractent', 'should withdraw'. 'Aeneadae', 'sons of Aeneas', his men, the patronymic used with contempt beside 'ignavi', 'cowardly'; Ae- is one long syllable. 'pepigere' = 'pepigerunt', 'they agreed', from 'pango', to strike a bargain: Aeneas had offered to settle the war by single combat (XI.115–118, from memory). Elisions 'mor(a) in', 'ignav(i) Aeneadae'."),
(13, 'foedus.',
 "I go to meet him; bring the sacred things, father, and frame the treaty.",
 "I will meet him: bring out the sacred things, father, and draw up the terms of the treaty.",
 "'Congredior', 'I meet (him)', the present for an immediate future; the verb is used of closing in combat. 'fer sacra', 'bring the sacred things', the victims and implements for the sacrifice that seals a treaty. 'pater', a respectful address to the old king, who is also to be his father-in-law. 'concipe foedus', 'frame the treaty', 'concipere' being the word for putting a formula into set words, as in 'concipere verba iuris iurandi'. No elisions."),
(17, 'coniunx.”',
 "Either with this right hand the Dardanian down to Tartarus I shall send,\nthe deserter of Asia (let them sit and watch, the Latins),\nand alone with the sword the common charge I shall refute,\nor let him have us conquered, let Lavinia pass to him as wife.”",
 "Either with this right hand I will send the Dardanian down to Tartarus, that runaway from Asia — let the Latins sit and look on — and with my sword alone refute the charge laid on us all, or let him hold us as his conquered subjects and take Lavinia as his bride.”",
 "'Aut… aut', 'either… or', the two outcomes. 'hac… dextra', 'with this right hand', with a gesture. 'Dardanium', 'the Dardanian', Aeneas, after Dardanus, founder of Troy's line; 'Tartara', neuter plural of Tartarus, the underworld. 'desertorem Asiae', 'deserter of Asia', a sneer: Aeneas fled when Troy fell. 'sedeant spectentque', jussive subjunctives, like 'habeat' and 'cedat' in 17. 'crimen commune', 'the reproach we share', the charge of cowardice. 'refellam', 'I will refute', from 're-' and 'fallo'. 'cedat… coniunx', 'let her go (to him) as wife'. The speech ends here. Elision 'desertor(em) Asiae'."),
(18, 'Latinus:',
 "To him with calmed heart answered Latinus:",
 "Latinus answered him with a quiet heart:",
 "A new paragraph in Greenough. 'Olli', the old form of 'illi', 'to him', from archaic 'ollus' for 'ille', kept in epic for its antique colour. 'sedato… corde', 'with a calmed heart', ablative of manner, framing the verb: the old king's composure set against Turnus's storm. No elisions."),
(21, 'casus.',
 "“O young man outstanding in spirit, as much as you yourself in fierce\nvalour excel, so much more earnestly it is right for me\nto take counsel and, fearing, to weigh all chances.",
 "“Young man of matchless spirit, the further you surpass others in fiery courage, the more it falls to me to take careful thought and, fearful as I am, weigh every hazard.",
 "Latinus's speech opens; it runs to 45. 'praestans animi', 'outstanding in spirit', 'animi' a genitive (or old locative) with an adjective, a poetic construction. 'quantum… tanto', 'by as much as… by so much', correlatives of comparison: the hotter you are, the more careful I must be. 'impensius', 'more earnestly', from 'impensus', costly. 'aequum est', 'it is right'. 'omnis… casus', the '-is' accusative plural, 'all chances'. 'expendere', 'weigh out', a word from the scales. Elisions throughout, e.g. 'quant(um) ipse', 'm(e) impensius', 'consuler(e) atque', 'metuent(em) expendere'."),
(23, 'est;',
 "You have the realms of your father Daunus, you have towns taken,\nmany, by your hand; and also both gold and goodwill Latinus has;",
 "You have the kingdom of your father Daunus, you have many towns taken by your own hand; and Latinus, too, has gold and a generous heart;",
 "'Sunt tibi', 'there are to you', the dative of possession, said twice: 'you have… you have'. Daunus, Turnus's father, king of the Rutulians at Ardea. 'manu', 'by (your) hand', by force. 'nec non', 'and also', two negatives making a strong positive. 'aurumque animusque', double '-que', 'both gold and spirit'; 'animus' is goodwill, readiness to give: Latinus is offering a rich settlement. 'Latino est', dative of possession again, the king speaking of himself by name. Elisions 'aurumqu(e) animusque', 'Latin(o) est'."),
(25, 'indecores.',
 "there are other unmarried girls in Latium and the Laurentine fields,\nnot in birth undistinguished.",
 "there are other unwed girls in Latium and the fields of Laurentum, and not of mean birth.",
 "'sunt aliae innuptae', 'there are other unmarried (girls)': Latinus is offering Turnus another bride. 'Latio et Laurentibus arvis', ablatives of place without a preposition. 'nec genus indecores', 'and not without distinction as to birth': 'genus' is an accusative of respect (the Greek construction), and 'indecores' comes from the rarer third-declension adjective 'indecoris', as 'indecorem' at XI.845. Elisions 'ali(ae) innuptae', 'Lati(o) et'."),
(26, 'hauri.',
 "Allow me these things, not soft to speak,\nwith wiles put away to lay open; at the same time drink this in with your mind.",
 "Let me lay bare these things, hard as they are to say, with all pretence set aside; and take this deep into your mind as well.",
 "'Sine me… aperire', 'allow me to disclose', 'sine' the imperative of 'sino', not the preposition. 'haud mollia fatu', 'not soft to speak', 'fatu' the supine in '-u' of 'for', saying in what respect: hard words. 'sublatis… dolis', ablative absolute, 'with deceits removed', without concealment. 'simul', 'at the same time', 'and with it'. 'animo hauri', 'drain this with your mind', take it in to the bottom, a metaphor from drinking. Elisions 'm(e) haec', 'anim(o) hauri'."),
(28, 'canebant.',
 "For me my daughter to none of her old suitors to join\nwas lawful, and this all, both gods and men, were foretelling.",
 "Heaven's law did not allow me to give my daughter to any of her former suitors, and all, gods and men alike, foretold as much.",
 "'Me… sociare… fas erat', 'it was right for me to join', the infinitive with subject accusative 'me' after 'fas erat', 'it was allowed by divine law'; the negative lies in 'nulli', 'to none'. 'veterum… procorum', 'of the old suitors', the Italian princes, Turnus among them, who sought Lavinia before the Trojans came. 'canebant', 'kept chanting', 'cano' of prophecy: the oracle of Faunus had told Latinus to wed her to a stranger from abroad (VII.96–101, from memory). 'divique hominesque', double '-que'. Elisions 'idqu(e) omnes', 'diviqu(e) hominesque'."),
(30, 'rupi:',
 "Overcome by love of you, by kindred blood overcome\nand by my sorrowing wife's tears, the bonds all I broke:",
 "Won over by my affection for you, won over by the blood we share and by my grieving wife's tears, I broke every bond:",
 "'Victus… victus', 'overcome… overcome', the word repeated (anaphora) by a man explaining his weakness. 'amore tui', 'by love of you', the objective genitive of the pronoun. 'cognato sanguine', 'by kindred blood': Turnus is kin to Amata, Latinus's queen (by tradition her sister's son, from memory). 'coniugis… maestae lacrumis', 'by the tears of my sad wife'; 'lacrumis' is Greenough's old spelling of 'lacrimis'. 'vincla', syncopated 'vincula', the bonds of oracle and promise. Elision 'vincl(a) omnia'."),
(31, 'sumpsi.',
 "the promised girl I snatched from my son-in-law, arms unholy I took up.",
 "I tore the promised bride from my son-in-law and took up an impious war.",
 "'promissam', 'the (girl) promised', Lavinia, pledged to Aeneas in Book VII. 'genero', 'from my son-in-law', a dative of separation with 'eripui': Latinus already calls Aeneas son-in-law. 'arma impia', 'impious arms': a war against an oracle and a promise is a sin. Two short clauses without a connective (asyndeton), the rhythm of a confession. Elisions 'promiss(am) eripui', 'arm(a) impia'."),
(33, 'labores.',
 "Since then what misfortunes me, what, Turnus, pursue,\nwhat wars, you see, how great the toils you first endure.",
 "Since then, Turnus, you see what misfortunes, what wars hound me, and what heavy trials you yourself are the first to bear.",
 "'Ex illo (tempore)', 'from that time'. 'qui… casus, quae… bella… sequantur', indirect questions after 'vides', with the subjunctive; 'quantos… patiare… labores' is a third. 'patiare' = 'patiaris', the alternative second-singular ending in '-re' (you will meet it often). 'primus', 'first, foremost': the leader takes the brunt. 'Turne', vocative, set inside the clause. No elisions."),
(35, 'Italas;',
 "Twice in a great battle beaten, barely within the city we guard\nthe hopes of Italy;",
 "Twice beaten in a great battle, we can barely guard the hopes of Italy behind our walls;",
 "'Bis… victi', 'twice beaten', in the battles of Books X and XI. 'magna… pugna', ablative of means, its words parted by 'victi'. 'urbe', 'in the city', ablative of place: the Latins are reduced to defending their walls. 'tuemur', 'we guard', a deponent. 'spes Italas', 'the hopes of Italy', the whole Italian cause. No elisions."),
(36, 'albent.',
 "warm again with our are the Tiber's streams\nblood still, and the plains, vast, with bones grow white.",
 "the waters of the Tiber are still warm with our blood, and the wide plains are white with bones.",
 "'recalent', 'are warm again', still warm, the 're-' marking a state that persists. 'Thybrina fluenta', 'the Thybrine streams', the Tiber under its poetic name 'Thybris'. 'nostro… sanguine', ablative of cause, split across the line-end. 'campique ingentes', 'and the vast plains'. 'albent', 'are white', with the bones of the unburied, a picture of long years of war though the fighting has lasted only days. Elisions 'sanguin(e) adhuc', 'campiqu(e) ingentes'."),
(37, 'totiens?',
 "Where am I carried back so often?",
 "Why do I keep drifting back?",
 "Latinus breaks off and turns on himself. 'Quo referor', 'where am I being carried back', a passive with the sense of being swept back, like a ship, to the old position. 'totiens', 'so many times': he has changed his mind again and again. A short self-reproaching question, the first of a series. No elisions."),
(37, 'mutat?',
 "What madness changes my mind?",
 "What madness keeps turning my judgement?",
 "'insania', 'madness', a hard word for his own wavering against the plain command of the oracle. 'mentem… mutat', 'changes my mind', a present of something that keeps happening: each time, the queen's tears and his own fondness undo his judgement. Elision 'ment(em) insania'."),
(39, 'tollo?',
 "If, Turnus slain, as allies I am ready to take them,\nwhy not, with him unharmed, rather do I end the contests?",
 "If I am prepared to take the Trojans as allies once Turnus is dead, why not end the fighting instead while he is still unharmed?",
 "'Turno exstincto', ablative absolute, 'Turnus being destroyed'; 'incolumi' (with 'Turno' understood), 'him being safe', a second ablative absolute set against the first. 'socios… adscire', 'to take on (the Trojans) as allies', 'socios' a predicate; 'adscire' is Greenough's spelling of 'ascire', 'to admit, adopt'. 'certamina tollo', 'do I remove the contest'. The logic is plain: a peace after his death is pointless when a peace before it would save him. Elision 'Turn(o) exstincto'."),
(42, 'petentem?',
 "What will the Rutulians, my blood-kin, what will the rest of\nItaly say, if you to death — may Chance unsay the words! —\nI should betray, you who seek my daughter and marriage with us?",
 "What will the Rutulians, my own kin, say, what will the rest of Italy say, if I betray you to death — may Chance prove the words false! — when you are seeking my daughter's hand and a marriage with my house?",
 "'consanguinei', 'of the same blood', the Rutulians as Latinus's kinsmen through Amata; one verb, 'dicet', serves both subjects. 'cetera… Italia', 'the rest of Italy', split across the line. 'si… prodiderim', 'if I should betray', perfect subjunctive in a future condition, seeing the deed as already done. 'Fors dicta refutet!', 'may Chance refute my words!', a wish thrown in between dashes to ward off the ill omen of saying 'death'. 'natam et conubia nostra petentem', 'seeking my daughter and marriage with us', the participle agreeing with 'te'; 'conubia', 'marriage(-rights)'. Elisions 'Itali(a) ad', 'nat(am) et'."),
(45, 'dividit.',
 "Consider the fortunes of war, how they change; pity your father,\naged, whom now, sorrowing, his homeland Ardea far away\nkeeps apart.”",
 "Consider how fortune shifts in war; have pity on your aged father, whom his homeland Ardea now keeps far from you and grieving.”",
 "The print has 'dividit. ”Haudquaquam', a misprint for 'dividit.” Haudquaquam', corrected here. The mark closing Latinus's speech is set after a space and joined to the next word, as at XI.849, so t keeps the print and the mark stands at the head of the next unit, while l and i close the speech after 'dividit.'. 'Respice', 'look back on, consider'. 'res bello varias', 'affairs changeable in war'. 'miserere', imperative of the deponent 'misereor', with the genitive 'parentis'. 'longaevi', 'long-lived, aged', Daunus. 'patria Ardea', his native town, the Rutulian capital. Elision 'patri(a) Ardea'."),
(46, 'flectitur:',
 "By no means by the words the violence of Turnus\nis bent:",
 "Turnus's violence is not swayed by his words in the least:",
 "The print has 'dividit. ”Haudquaquam', a misprint for 'dividit.” Haudquaquam', corrected here; the mark at the head of t belongs to the speech just ended, so l and i carry none. 'Haudquaquam', 'by no means', a strong negative. 'dictis', ablative of means, Latinus's words. 'violentia Turni', the word of line 9 again, almost a character in its own right. 'flectitur', 'is bent', the image of trying to turn something rigid. No elisions."),
(46, 'medendo.',
 "it rises the more and sickens with the healing.",
 "it mounts the higher and grows worse for being treated.",
 "'exsuperat', 'surges over', a word used of flames or a flood rising above a barrier. 'aegrescit… medendo', 'grows sick through healing', 'medendo' a gerund in the ablative, 'by the treating': the doctor's attempt makes the patient worse. The medical metaphor makes Turnus's rage a disease, and the paradox is compact enough to be quoted on its own. No elisions."),
(47, 'ore:',
 "As soon as to speak he was able, thus he began with his lips:",
 "As soon as he could find his voice, he began:",
 "'Ut primum', 'as soon as', with the perfect. 'fari potuit', 'he was able to speak': rage at first chokes him. 'institit', 'set about (speaking)', from 'insisto', to press on with something. 'ore', 'with his mouth', making the speaking physical, a fuller version of the usual formula of address. No elisions."),
(49, 'pacisci:',
 "“The care which for me you bear, this, I pray, best of men, for me\nlay aside, and allow me death for glory to bargain:",
 "“The concern you feel for me, best of men, I beg you, put it aside for my sake, and let me trade my death for glory:",
 "Turnus's reply opens; it runs to 53. 'Quam… curam… hanc', 'what care… this (care)', the relative clause put first and picked up by the demonstrative. 'pro me… pro me', 'for me… for my sake', the same words with a new turn. 'precor… deponas', 'I pray you lay aside', the subjunctive without 'ut' after a verb of asking. 'optime', 'best (of men)', a courteous vocative. 'letum… pro laude pacisci', 'to bargain death for glory', 'pacisci' a deponent, 'to make a bargain': the heroic exchange chosen by Achilles. No elisions."),
(51, 'spargimus;',
 "We too weapons, father, and steel not feeble with our right hand\nscatter;",
 "I too, father, can hurl spears and steel with no feeble hand;",
 "'et nos', 'we too': 'nos' is Turnus himself, the poetic plural, and 'et' means 'also', as well as Aeneas. 'tela… ferrumque', 'missiles and steel'. 'haud debile', 'not feeble', understatement (litotes) for 'strong'. 'dextra', 'with the right hand', ablative of instrument. 'spargimus', 'we scatter', throw broadcast. Elision 'ferrumqu(e) haud'."),
(51, 'sanguis.',
 "and from our wound follows blood.",
 "and the wounds I give draw blood as well.",
 "'nostro… de volnere', 'from a wound of ours', one we give, not one we take; 'volnere' is Greenough's old spelling of 'vulnere'. 'sequitur', 'follows', the blood coming after the blow. Aeneas is not the only one whose spear does harm: Turnus answers Latinus's fear for him with a boast. No elisions."),
(53, 'umbris.”',
 "Far away for him his goddess mother will be, to cover the runaway in a cloud\nwomanish and hide herself in empty shadows.”",
 "His goddess mother will be far from him, with no woman's cloud to shield her runaway and no empty shadows for her to hide in.”",
 "The print has lower-case 'longe' after the full stop ending 51, a misprint for 'Longe', corrected here. 'longe… erit', 'will be far off'; 'illi', 'for him', Aeneas. 'dea mater', Venus. 'quae… tegat… occulat', a relative clause of purpose, 'to hide': there will be no goddess at hand to do it. In the Iliad Aphrodite carries Aeneas away from Diomedes in her robe and Apollo then hides him in a dark cloud (V.311–345, from memory). 'nube… feminea', 'a womanish cloud', a sneer at a man saved by his mother. 'fugacem', 'the runaway'. 'sese', grammatically the goddess herself. The speech ends here. Elisions 'long(e) illi', 'ses(e) occulat'."),
(55, 'tenebat:',
 "But the queen, by the new turn of the fight terrified,\nwas weeping, and her fiery son-in-law, meaning to counsel him, was holding:",
 "But the queen, terrified at this new turn in the contest, was weeping, and clung to her fiery son-in-law, intent on counselling him:",
 "A new paragraph in Greenough. 'regina', Amata, Latinus's queen and Turnus's champion since Book VII. 'nova pugnae… sorte', 'by the new lot of the fight', the single combat now agreed. 'generum', 'son-in-law', as she still calls Turnus. 'monitura', future participle of 'moneo', 'meaning to warn': Greenough's reading. The Latin Library has 'moritura', 'resolved to die', which turns her whole speech into the plea of a woman set on death (she says she will not outlive him, 62–63) and looks ahead to her end in this book; both construe, and the sense differs. 'flebat… tenebat', imperfects, a scene held still. No elisions."),
(60, 'oro:',
 "“Turnus, by these, I beg you, tears, by whatever regard for Amata\ntouches your heart (you are now my one hope, of my old age\nyou are the rest, my wretched age; the glory and the power of Latinus\nlie with you, on you the whole house leans and rests),\none thing I beg:",
 "“Turnus, by these tears, by whatever regard for Amata touches your heart — you are my one hope now, the comfort of my unhappy age, the honour and the sovereignty of Latinus are in your keeping, the whole house leans its weight on you — one thing I beg of you:",
 "The print has 'recumbit).' with a full stop, then lower-case 'unum', a misprint for a comma, corrected here: the oath 'per has… lacrimas, per… honos' needs its verb and finds it in 'oro'. t keeps the print and the unit runs on across the stop. Amata's speech opens; it runs to 63. 'per has ego te lacrimas', 'by these tears I (beg) you', the pronouns set between 'per' and its noun, the word order of entreaty. 'siquis… honos', 'if any regard'. 'senectae… miserae', 'of my unhappy old age'. 'te penes', 'in your keeping', 'penes' after its pronoun. 'inclinata recumbit', 'leans and rests', a falling house on its one prop. Elisions 'in t(e) omnis', 'un(um) oro'."),
(60, 'Teucris.',
 "cease to join hands with the Teucrians.",
 "give up meeting the Trojans hand to hand.",
 "'desiste', 'stop, desist', with the infinitive. 'manum committere', 'to join hand (in battle)', the idiom of 'manum' or 'proelium committere', to engage. 'Teucris', dative, 'with the Teucrians', the Trojans, named after their ancestor Teucer; 'eu' is one syllable. The whole of Amata's speech hangs on this one plea. No elisions."),
(62, 'manent:',
 "Whatever misfortunes await you in that contest of yours,\nme too, Turnus, they await:",
 "Whatever fate awaits you in that contest awaits me too, Turnus:",
 "'Qui… cumque', 'whatever', 'quicumque' split by 'te' (tmesis, a word cut in two). 'manent', 'await', with an accusative of the person. 'isto certamine', 'in that contest of yours', 'iste' with a note of distaste. 'et me', 'me also'. The repeated verb ties her fate to his. No elisions."),
(63, 'videbo.”',
 "at once this hateful I shall leave\nlight, and not Aeneas as son-in-law, a captive, shall I see.”",
 "I will quit this hateful daylight together with you, and never be a captive who sees Aeneas made my son-in-law.”",
 "'simul', 'together, at the same moment', with you. 'haec… lumina', 'this light', the daylight of life, and 'invisa', 'hateful': she means to die. 'generum Aenean', 'Aeneas as son-in-law', 'generum' a predicate; 'Aenean' is a Greek accusative, its Ae- one long syllable. 'captiva', 'a captive', what she would be in a Trojan victory. The words look ahead to her death later in this book. The speech ends here. Elision 'gener(um) Aenean'."),
(66, 'cucurrit.',
 "Lavinia took in her mother's words, with tears\nher burning cheeks drenched, in whom a deep fire\na blush kindled beneath, and over her heated face it ran.",
 "Lavinia heard her mother's words, her burning cheeks bathed in tears, while a deep blush lit a fire in her and spread over her glowing face.",
 "'Accepit vocem… matris', 'took in her mother's voice', heard her. 'lacrimis… perfusa genas', 'drenched as to her cheeks with tears', 'genas' an accusative of respect (the Greek construction, common with passive participles). 'quoi' is Greenough's old spelling of 'cui', 'to whom', a dative of reference: 'in whom'. 'plurimus… rubor', 'a deep blush', which 'ignem subiecit', 'set fire beneath', like fuel kindled under a pot. Virgil does not say why she blushes. This is the one moment in the poem where Lavinia shows any feeling, and she never speaks. No elisions."),
(69, 'rosa:',
 "As if Indian with blood-red should stain purple\nsomeone ivory, or as when, mingled, lilies blush, white,\nwith much rose:",
 "As when someone stains Indian ivory with blood-red purple, or when white lilies blush with many roses set among them:",
 "'veluti… siquis… violaverit', 'as if someone should stain', the perfect subjunctive in a simile of supposed action. 'Indum… ebur', 'Indian ivory', framing the clause; 'ostro', 'with purple dye', the costly sea-purple; 'violaverit', 'has stained', but also 'has violated', a hint of hurt inside the picture of beauty. Homer compares blood on Menelaus's thigh to a woman staining ivory with purple (Iliad IV.141–147, from memory). 'mixta… multa… rosa', 'mingled with much rose', the ablative 'multa… rosa' parted from 'mixta'; 'alba' agrees with 'lilia'. No elisions."),
(69, 'colores.',
 "such colours the maiden was giving in her face.",
 "such were the colours that came and went in the maiden's face.",
 "'talis… colores', 'such colours', framing the clause and closing the simile. 'virgo', Lavinia. 'dabat ore', 'was giving in her face', showed; 'ore' is an ablative of place, 'os' the face. Red on white was the ancient picture of a beautiful complexion, and the blush is all we are told of what she feels. No elisions."),
(70, 'voltus:',
 "Him love throws into turmoil, and he fixes on the maiden his looks:",
 "Love throws Turnus into turmoil, and he fastens his eyes on the girl:",
 "'Illum', Turnus, put first. 'turbat amor', 'love unsettles (him)', the only place in the poem where Turnus is said to love Lavinia. 'figit… voltus', 'fixes his looks', 'voltus' Greenough's old spelling of 'vultus', plural for the face or gaze. 'in virgine', 'on the maiden'. Elision 'figitqu(e) in'."),
(71, 'Amatam.',
 "he burns for arms the more, and in few words addresses Amata.",
 "He burns all the more for the fight, and speaks a few words to Amata.",
 "'ardet in arma', 'burns towards arms', 'in' of purpose, eager for battle. 'magis', 'the more': the sight of her sharpens his resolve. 'paucis (verbis)', 'in a few words'. 'adfatur', 'addresses', Greenough's spelling of 'affatur', as at 10. Elision 'paucisqu(e) adfatur'."),
(74, 'mater;',
 "“Do not, I beg, do not with tears or with so great an omen\nsee me off, as into the contests of harsh Mars I go,\nO mother;",
 "“Do not, I beg you, mother, do not send me off with tears and so dark an omen as I go into the trials of cruel war;",
 "Turnus's reply opens; it runs to 80. 'Ne… prosequere', 'do not escort', 'ne' with the present imperative of the deponent, a poetic and old-fashioned prohibition. 'neve', 'or not'. 'omine tanto', 'with so great an omen': tears at a parting were thought to bring bad luck. 'duri certamina Martis', 'the contests of hard Mars', war. 'euntem', 'going', agrees with 'me'. 'O mater': he addresses his future mother-in-law as mother. Elisions 'nev(e) omine', 'prosequer(e) in'."),
(74, 'mortis.',
 "for not to Turnus is the delaying of death free.",
 "for Turnus is not free to put off his death.",
 "'neque enim', 'for… not'. 'Turno… mora libera mortis', 'to Turnus (there is) no free delay of death', dative of possession: whether his death comes now or later is not his to choose, and if it is fated, tears will not hold it back. 'mortis', objective genitive with 'mora'. The thought is Hector's to Andromache, that no man dies before his destined day (Iliad VI.487–489, from memory). Elision 'nequ(e) enim'."),
(76, 'refer:',
 "As messenger these, Idmon, to the Phrygian tyrant, my words,\nnot going to please, carry back:",
 "Idmon, be my messenger and carry these words of mine to the Phrygian tyrant, words he will not like:",
 "'Idmon', a herald, named only here; 'nuntius', 'as messenger', in apposition. 'Phrygio… tyranno', 'to the Phrygian tyrant', Aeneas: 'Phrygian' is contemptuous, the soft Asiatic, and 'tyrannus', a Greek word for a ruler, can mean simply 'king' but here carries its sting. 'haec… mea dicta… haud placitura', 'these words of mine, not going to please', the future participle. 'refer', 'carry back'. No elisions."),
(79, 'Rutuli;',
 "as soon as tomorrow's in the sky,\non crimson borne wheels, Dawn grows red,\nlet him not lead the Teucrians against the Rutulians; let the Teucrians' arms rest,\nand the Rutulians;",
 "as soon as tomorrow's Dawn, borne on her crimson wheels, reddens in the sky, let him not lead Trojans against Rutulians; let the Trojans' arms be still, and the Rutulians too;",
 "'cum primum', 'as soon as', with a future. 'crastina… Aurora', 'tomorrow's Dawn', the goddess driving her chariot ('rotis', 'wheels') into the sky; 'puniceis', 'crimson', a word related to 'Poenus', Phoenician, from the Tyrian dye. 'non… agat', 'let him not lead', jussive with 'non' for the usual 'ne'. 'Teucrum' = 'Teucrorum', the old genitive plural; 'eu' is one syllable in 'Teucros' and 'Teucrum'. 'et Rutuli', 'and (let) the Rutulians (rest)', a second subject added loosely. Elision 'Teucr(um) arma'."),
(80, 'campo.”',
 "with our let us settle blood the war;\non that let be sought as wife Lavinia field.”",
 "let us decide the war with our own blood; on that field let Lavinia be won as a bride.”",
 "'dirimamus', 'let us decide', jussive; 'dirimo' is literally 'part, separate', the word for breaking up a fight. 'nostro… sanguine', 'with our blood', his and Aeneas's: the plural takes in both champions. 'illo… campo', 'on that field', framing the line, ablative of place. 'quaeratur', 'let her be sought', won. 'coniunx', 'as wife', a predicate. The speech ends here. No elisions."),
(84, 'auras.',
 "These words when he had spoken and swiftly into the palace withdrawn,\nhe calls for his horses and rejoices, watching before his face them snorting,\nwhich to Pilumnus as a glory Orithyia herself gave,\nwhich in whiteness would outdo snows, in running the winds.",
 "When he had said this and hurried back into the palace, he called for his horses and delighted to watch them snorting before his eyes, the team that Orithyia herself gave Pilumnus as a prize, fit to outshine the snow in whiteness and the winds in speed.",
 "A new paragraph in Greenough. The print has 'recessit.' with a full stop, then lower-case 'poscit', a misprint for a comma, corrected here: 'ubi… dedit… recessit' is a clause of time whose main verb is 'poscit'. t keeps the print and the unit runs on across the stop. 'Haec ubi dicta dedit', the formula that ends a speech. 'frementis', '-is' accusative plural, 'snorting'. 'Pilumno', Pilumnus, an old Italian god and Turnus's ancestor. 'Orithyia', the Athenian princess carried off by Boreas, the North Wind: horses bred of the wind. 'decus', 'as a glory', in apposition. 'qui… anteirent', a relative clause of characteristic, 'such as to outstrip'; 'antei-' is run together as two syllables. Elisions 'rapidusqu(e) in', 'ant(e) ora'."),
(86, 'pectunt.',
 "Around them stand the busy grooms, and with hands they rouse\nthe chests, patted with hollow palms, and the maned necks comb.",
 "The grooms stand round in haste, rousing the horses with the slap of cupped hands on their chests and combing their flowing manes.",
 "'properi', 'hurrying', an adjective with adverbial force. 'aurigae', 'charioteers', here the grooms who tend the team. 'manibus… cavis', 'with hollow hands', cupped palms that make a ringing slap, the adjective parted from its noun across the line. 'lacessunt pectora plausa', 'they excite the chests, patted', i.e. they rouse them by patting: the participle tells how. 'colla comantia', 'maned necks'; 'pectunt', 'they comb', a sound-play on 'pectora'. Elision 'proper(i) aurigae'."),
(88, 'umeris;',
 "He himself then, with gold rough and with white orichalc,\nputs the breastplate around his shoulders;",
 "Then Turnus himself fastens about his shoulders a breastplate stiff with gold and pale orichalc;",
 "'Ipse', Turnus himself, after the grooms. 'dehinc', 'next', here two syllables (it is often run together into one). 'squalentem', 'rough, scaly', thick with ornament, like a snake's scales. 'orichalco', 'orichalc', a precious pale alloy, in Greek 'mountain-copper', which Latin also spelt 'aurichalcum' as if 'gold-copper'; 'albo', 'white', its pale sheen. 'circumdat… umeris', 'puts around his shoulders', with the dative; 'umeris' is Greenough's spelling of 'humeris'. Elisions 'squalent(em) alboque', 'alboqu(e) orichalco', 'loric(am) umeris'."),
(91, 'unda.',
 "at the same time he fits for holding\nboth the sword and the shield and the horns of the red crest,\nthe sword which for Daunus, his father, the fire-lord god himself\nhad made, and glowing in Stygian water had dipped.",
 "At the same time he fits himself with sword and shield and the horns of his crimson crest — the sword that the fire-lord god himself had made for his father Daunus and plunged glowing into the waters of the Styx.",
 "The print has 'cristae.' with a full stop, then lower-case 'ensem', a misprint for a comma, corrected here: 'ensem' in 90 takes up 'ensemque' and begins the sword's history. t keeps the print and the unit runs on across the stop. 'aptat habendo', 'fits for holding', the dative of the gerund for purpose: he makes them ready to his grip. 'ensemque clipeumque', double '-que'. 'cornua cristae', the horns that held the plume of his helmet. 'ignipotens', 'lord of fire', Vulcan, who also made Aeneas's arms in Book VIII. 'Stygia… unda', 'in Stygian water', the quenching that tempers steel, given an infernal touch. Elisions 'clipeumqu(e) et', 'Daun(o) ignipotens'."),
(95, 'vociferans:',
 "Next, which in the middle against a huge column leaning\nof the hall stood, the strong spear with force he seizes,\nthe spoil of Actor the Auruncan, and shakes it, quivering,\nshouting:",
 "Then he wrenches up the strong spear that stood propped against a huge column in the middle of the hall, spoil taken from Actor the Auruncan, and shakes it till it quivers, shouting:",
 "'Exin', 'next', Greenough's form of 'exinde' (the Latin Library prints 'exim'). The relative clause 'quae… adstabat' comes before its noun, 'hastam', so the spear is described before it is named. 'mediis… aedibus', 'in the middle of the house', split across the line-end. 'adnixa', 'leaning against', with the dative 'columnae'; 'adstabat' is Greenough's spelling of 'astabat'. 'validam vi', strength set against strength. 'Actoris Aurunci spolium', 'spoil of Actor the Auruncan', in apposition, a spear taken from a beaten enemy; the Aurunci were an old people of Campania. 'trementem', 'quivering', the result of the shaking. Elision 'ingent(i) adnixa'."),
(97, 'gerit.',
 "“Now, O never having cheated the summons,\nspear, of mine, now the time is here: you mighty Actor,\nyou now Turnus's right hand carries.",
 "“Now, spear, you that never failed me when I called on you, now the hour has come: once great Actor carried you, now Turnus's hand bears you.",
 "Turnus's address to his spear opens; it runs to 100. 'O numquam frustrata vocatus… meos', 'O you who never cheated my calls', 'frustrata' a deponent participle with active sense, 'vocatus' the accusative plural of the fourth-declension noun 'vocatus', 'summons'. 'nunc… nunc… nunc', the triple 'now' of a man who cannot wait. 'te… te', the repeated pronoun: a weapon passes from one great owner to another. 'gerit', 'bears', with 'gerebat' to be supplied for Actor. A speech to a weapon is rare in epic; Achilles speaks to his horses in Homer (Iliad XIX.400–403, from memory). No elisions."),
(100, 'madentis.”',
 "Grant me to lay low the body\nand the breastplate with strong hand to tear, wrenched off,\nof the half-man Phrygian, and to befoul in the dust his locks,\ncurled with the hot iron and with myrrh dripping.”",
 "Grant me to lay low the body of that Phrygian half-man, to wrench off his breastplate and tear it with a strong hand, and to foul in the dust his hair, crimped with hot irons and dripping with myrrh.”",
 "'Da', 'grant', with three infinitives, 'sternere… lacerare… foedare'. 'loricamque… revulsam', 'and the breastplate torn away', the participle telling what is done first. 'semiviri Phrygis', 'of the half-man Phrygian', the old Italian sneer at Trojan softness (Iarbas uses 'semivir' of Aeneas's company in Book IV, from memory). 'crinis', '-is' accusative plural, 'hair'. 'vibratos calido ferro', 'curled with the hot iron', curling tongs; 'murra', myrrh, a perfumed oil: Turnus jeers at a dandy. The speech ends here. Elision 'foedar(e) in'."),
(101, 'furiis;',
 "By these he is driven, furies;",
 "Such is the frenzy that drives him;",
 "'His… furiis', 'by these furies', ablative of cause: the Furies were the goddesses of madness and vengeance, and 'furiae' is also simply 'frenzy'. 'agitur', 'is driven', like an animal under the goad. A short clause that sums up the speech before the picture of his blazing face. No elisions."),
(102, 'ignis:',
 "and from the whole face of him burning\nsparks leap away, in his keen eyes flashes fire:",
 "sparks fly from all his blazing face, and fire flashes from his fierce eyes:",
 "'toto… ab ore', 'from his whole face', framing the clause; 'ardentis', genitive, 'of him blazing'. 'scintillae absistunt', 'sparks stand off, fly away', an unusual use of 'absisto'. 'oculis… acribus', 'in his keen eyes', ablative of place. Virgil makes the metaphor of fiery rage literal, as Homer does with the flame that blazes from Achilles' head (Iliad XVIII.205–214, from memory). Elisions 'totoqu(e) ardentis', 'scintill(ae) absistunt'."),
(106, 'harena.',
 "bellowings as when before his first battles a bull\nterrifying raises and to put his anger into his horns tries,\nagainst a tree's trunk thrusting, and the winds provokes\nwith blows, or with sand scattered for the fight rehearses.",
 "just as a bull before his first battle raises terrible bellowings and tries to gather his anger into his horns, butting against a tree-trunk and striking at the winds, or tosses up the sand in a prelude to the fight.",
 "'veluti cum', 'as when', a simile Virgil had drawn already in Georgics III, of a bull training for battle (from memory). 'mugitus… terrificos', 'terrifying bellowings', parted across the line-end. 'ciet', 'stirs up, raises'. 'irasci in cornua', 'to put his anger into his horns', to gather his rage into them. 'obnixus', 'pressing against', with the dative 'trunco'. 'ventos lacessit ictibus', 'provokes the winds with blows', thrusts at empty air. 'proludit', 'practises beforehand', a gladiator's word. The Latin Library reads 'aut' for 'atque' in 104, making the bellowing and the trial of the horns alternatives; the sense hardly changes. Elisions 'prim(a) in', 'atqu(e) irasci', 'irasc(i) in', 'spars(a) ad'."),
]

# Speech-mark check exemptions (rule 5b), by unit ln:
#  43: the print closes Latinus's speech with a mark set after a space and joined to 'Haudquaquam'
#      ('dividit. ”Haudquaquam'); t ('Respice… dividit.') lacks the mark, l and i close the speech after 'dividit.'.
#  45: the mark stands at the head of t ('”Haudquaquam'); l and i carry none.
EXEMPT = {43, 45}
P = A.part('aeneid-091'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']} | {L[0]['n']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL: print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and ln not in EXEMPT: print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and ln not in EXEMPT: print('MARK i', ln, mk)
    if '“' in n or '”' in n:
        if ln not in EXEMPT: print('DOUBLE MARK IN n', ln)
covered = sorted({ln + k for (t, ln) in cuts for k in range(t.count('\n') + 1)})
if covered != [l['n'] for l in L]: print('COVERAGE', covered)
joined = '\n'.join(l['t'] for l in L)
rebuilt = ''.join(t + ('\n' if (k + 1 < len(cuts) and cuts[k + 1][1] != ln + t.count('\n')) else ' ' if k + 1 < len(cuts) else '') for k, (t, ln) in enumerate(cuts))
if rebuilt != joined: print('JOIN MISMATCH')
if A.sha(L) != P.get('sha256', A.sha(L)): print('SHA MISMATCH')
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units;', len(covered), 'lines covered')
